INSERT INTO page (id, type, slug, titre, titre_cle, resume, donnees, corps_md, statut, origine, source_ref) VALUES ('capacites/mage-rouge-preparation', 'capacites', 'mage-rouge-preparation', 'Préparation (Mage Rouge)', 'preparation-mage-rouge', 'Permet de charger un sort d''attaque lvl1 ou lvl2 le premier tour et de l''utiliser en même temps que l''attaque de contact le tour suivant.', '{"classe": "classes/mage-rouge", "niveau": 1, "nature": "classe", "rang": 1, "ligne": 4, "type_capacite": "Action"}', 'Permet de charger un sort d''attaque lvl1 ou lvl2 le premier tour et de l''utiliser en même temps que l''attaque de contact le tour suivant.

Note de cellule : Le sort prend en compte la posture le moment où il a été chargé pour le calcul des dégâts de ce dernier.

La posture focus transforme ce don en IC.

Le sort en question ne se met pas sur l''arme mais bien dans la main.
', 'draft', 'classes', 'Google Sheet « Classe Maverick V7 », onglet « Mage Rouge »');
INSERT INTO page (id, type, slug, titre, titre_cle, resume, donnees, corps_md, statut, origine, source_ref) VALUES ('capacites/mage-rouge-utilise-ta-tete', 'capacites', 'mage-rouge-utilise-ta-tete', 'Utilise ta tête (Mage Rouge)', 'utilise-ta-tete-mage-rouge', 'Permet de charger un sort à la tête plutôt qu''une main.', '{"classe": "classes/mage-rouge", "specialite": "MAGE RUBIS", "niveau": 20, "nature": "choix", "rang": 1, "ligne": 43, "type_capacite": "Passif", "choix_exclusif_avec": ["capacites/mage-rouge-instant-sort"]}', 'Permet de charger un sort à la tête plutôt qu''une main. Ce qui permet d''utiliser une arme à 2 mains ou 2 armes en plus du sort chargé.
', 'draft', 'classes', 'Google Sheet « Classe Maverick V7 », onglet « Mage Rouge »');
