INSERT INTO page (id, type, slug, titre, titre_cle, resume, donnees, corps_md, statut, origine, source_ref) VALUES ('lore/les-divinites', 'lore', 'les-divinites', 'Les Divinités', 'les-divinites', 'Le panthéon de Maverick : forces créatrice et destructrice, dieux primordiaux, dieux et autres êtres divins.', NULL, 'Dans Maverick, il existe un grand panthéon, des êtres supérieurs qui représente un thème, une magie, un concept :

## Force créatrice

- [[Tofrom]] — Force Créatrice

## Force destructrice

- [[Morfot]] — Force Destructrice

## Primordiaux

- [[Brock]] — Dieu primordial de la force
- [[Mirada]] — Déesse primordiale du {{chakra|chakra}}
- [[Notix]] — Dieu primordial du temps
- [[Capse]] — Déesse primordiale de l''espace

## Dieux

- [[Séraphe]] — Dieu de la guerre
- [[Evravonie]] — Déesse de la vie et de la mort
- [[Séraphin]] — Dieu du feu
- [[Océane]] — Déesse de l''eau
- [[Celsius]] — Déesse de la glace
- [[Dimitri]] — Dieu de la terre
