INSERT INTO page (id, type, slug, titre, titre_cle, resume, donnees, corps_md, statut, origine, source_ref) VALUES ('ressources/huile-assourdissante', 'ressources', 'huile-assourdissante', 'Huile assourdissante', 'huile-assourdissante', 'L’Huile Assourdissante est une préparation alchimique conçue pour être appliquée sur une arme afin d’infliger l’altération d’état surdité.', NULL, '*L’Huile Assourdissante est une préparation alchimique conçue pour être appliquée sur une arme afin d’infliger l’altération d’état surdité. Issue d’ingrédients liés au vent, elle permet de transmettre cet effet à chaque coup porté, perturbant l’audition de la cible et réduisant sa perception de l’environnement. Plus l’huile est puissante, plus le nombre d’utilisations avant dissipation est élevé.*

