INSERT INTO page (id, type, slug, titre, titre_cle, resume, donnees, corps_md, statut, origine, source_ref) VALUES ('ressources/remede-enrage', 'ressources', 'remede-enrage', 'Remède enragé', 'remede-enrage', 'Le Remède Enragé est une préparation alchimique conçue pour calmer les esprits submergés par une rage incontrôlable.', NULL, '*Le Remède Enragé est une préparation alchimique conçue pour calmer les esprits submergés par une rage incontrôlable. Issu d’un mélange de substances liées au vide et à l’espace/temps, il agit en brisant l’élan de fureur et en ramenant le buveur à un état plus stable. En combat, il permet de réduire rapidement l’intensité de l’enragement, voire de le dissiper complètement pour les versions les plus puissantes. Utilisé sur la durée, il aide à apaiser les accès de rage persistants, permettant à l’esprit de retrouver contrôle et lucidité.*

